B.b6V=new A.G(B.n,["You chose the package. In-app purchase (App Store / Google Play) is not open yet; nothing was charged and nothing went live.","Paketi se\xe7tin. Uygulama i\xe7i sat\u0131n alma (App Store / Google Play) hen\xfcz a\xe7\u0131lmad\u0131; senden hi\xe7bir \xfccret al\u0131nmad\u0131 ve yay\u0131n ba\u015flamad\u0131."],t.w)
B.b1E=new A.G(B.n,["You have many suggestions in review; wait for them first.","\u0130ncelemede \xe7ok say\u0131da \xf6nerin var; sonu\xe7lanmalar\u0131n\u0131 bekle."],t.w)
B.bc2=new A.G(B.n,["You have no plans left right now. Yumy Credits or Yumy Plus let you continue.","Plan hakk\u0131n \u015fu an bitti. Devam etmek i\xe7in Yumy Kredisi ya da Yumy Plus gerekir."],t.w)
B.bdh=new A.G(B.n,["You have no trips yet.","Hen\xfcz gezin yok."],t.w)
B.b3N=new A.G(B.n,["You have no verified business authorization for this place.","Bu mek\xe2n i\xe7in do\u011frulanm\u0131\u015f i\u015fletme yetkin yok."],t.w)
B.b6_=new A.G(B.n,["You have not chosen a duration yet.","Hen\xfcz bir s\xfcre se\xe7medin."],t.w)
